param([Parameter(Mandatory=$true)][string]$SourceRoot,[Parameter(Mandatory=$true)][string]$OutputDirectory)
$ErrorActionPreference='Stop'
function Get-Median([double[]]$Values){$a=@($Values|Sort-Object);if($a.Count -eq 0){return $null};if($a.Count%2 -eq 1){return [double]$a[[int]($a.Count/2)]};return ([double]$a[$a.Count/2-1]+[double]$a[$a.Count/2])/2.0}
$runRows=[Collections.Generic.List[object]]::new()
$allProcesses=[Collections.Generic.List[object]]::new()
foreach($file in Get-ChildItem -LiteralPath (Join-Path $SourceRoot 'runs') -Recurse -Filter 'process.json'){
 $p=Get-Content -LiteralPath $file.FullName -Raw|ConvertFrom-Json
 $allProcesses.Add($p)
 $resultPath=Join-Path $file.Directory.FullName 'output\result.jsonl';$r=$null;if(Test-Path -LiteralPath $resultPath){$r=Get-Content -LiteralPath $resultPath -Raw|ConvertFrom-Json}
 $timeout=($null -eq $p.exit_code -and [double]$p.duration_ms -ge 899000 -and $null -eq $r)
 $l0ratio=$null;$l1ratio=$null;$coldPct=$null;$failureCount=$null
 if($null -ne $r){$l0b=[double]$r.lod0_baseline_build_us.p50;$l0o=[double]$r.lod0_optimized_build_us.p50;$l1b=[double]$r.lod1_baseline_build_us.p50;$l1o=[double]$r.lod1_optimized_build_us.p50;if($l0b -gt 0){$l0ratio=$l0o/$l0b};if($l1b -gt 0){$l1ratio=$l1o/$l1b};$den=$l1b+[double]$r.lod1_serialization_us;if($den -gt 0){$coldPct=100*([double]$r.cache_first_lookup_us/$den-1)};$failureCount=@($r.failures|Where-Object{$_}).Count}
 $adaptive=$null;if($r){$adaptive=$r.adaptive_policy}
 $runRows.Add([pscustomobject]@{run_id=$p.run_id;scenario=$p.scenario;scenario_id=if($r){$r.scenario_id}else{$p.expected_scenario_id};repeat=$p.repeat;source_sha=$p.source_sha;launcher_pid=$p.godot_wrapper_pid;engine_pid=$p.engine_pid;engine_parent_pid=$p.engine_parent_pid;attribution=$p.process_attribution;process_status=$p.status;exit_code=$p.exit_code;duration_ms=$p.duration_ms;timeout_censored=$timeout;result_validation=$p.result_validation;result_status=if($r){$r.status}else{'MISSING'};result_failure_count=$failureCount;query_mismatches=if($r){$r.query_mismatches}else{$null};normal_mismatches=if($r){$r.normal_mismatches}else{$null};picker_mismatches=if($r){$r.picker_mismatches}else{$null};lod0_mesh_equal=if($r){$r.lod0_mesh_equal}else{$null};lod1_mesh_equal=if($r){$r.lod1_mesh_equal}else{$null};lod0_ratio=$l0ratio;lod1_ratio=$l1ratio;lod0_baseline_p50_us=if($r){$r.lod0_baseline_build_us.p50}else{$null};lod0_optimized_p50_us=if($r){$r.lod0_optimized_build_us.p50}else{$null};lod1_baseline_p50_us=if($r){$r.lod1_baseline_build_us.p50}else{$null};lod1_optimized_p50_us=if($r){$r.lod1_optimized_build_us.p50}else{$null};cold_overhead_pct=$coldPct;cache_first_layer=if($r){$r.cache_first_layer}else{$null};cache_first_lookup_us=if($r){$r.cache_first_lookup_us}else{$null};cache_disk_hit_us=if($r){$r.cache_fresh_instance_disk_hit_us}else{$null};cache_hits=if($r){$r.cache_hits}else{$null};cache_misses=if($r){$r.cache_misses}else{$null};cache_remote_edit_lookup_us=if($r){$r.cache_remote_edit_lookup_us}else{$null};cache_local_edit_rebuild_us=if($r){$r.cache_local_edit_rebuild_us}else{$null};cache_disk_bytes=if($r){$r.cache_disk_bytes}else{$null};cache_memory_bytes=if($r){$r.cache_memory_bytes}else{$null};static_memory_delta_bytes=if($r){$r.static_memory_delta_bytes}else{$null};sampled_peak_working_set_bytes=$p.sampled_peak_working_set_bytes;sampled_peak_private_bytes=$p.sampled_peak_private_bytes;candidate_operations=if($r){$r.meshing_candidate_count}else{$null};adaptive_bypasses=if($adaptive){$adaptive.bypass_count}else{$null};adaptive_reduction_pct=if($adaptive){$adaptive.cold_overhead_reduction_percent}else{$null};adaptive_unconditional_overhead_us=if($adaptive){$adaptive.unconditional_cold_overhead_us}else{$null};adaptive_policy_overhead_us=if($adaptive){$adaptive.policy_cold_overhead_us}else{$null};command_sha256=if($r){$r.command_sha256}else{$null}})
}
$runRows|Export-Csv -LiteralPath (Join-Path $OutputDirectory 'run-summary.csv') -NoTypeInformation -Encoding UTF8
$scenarioRows=[Collections.Generic.List[object]]::new()
foreach($group in ($runRows|Group-Object scenario|Sort-Object Name)){$g=@($group.Group);$valid=@($g|Where-Object { $_.process_status -eq 'EXIT_ZERO' -and $_.result_status -eq 'PASS' -and $_.result_failure_count -eq 0 });$r3c=$group.Name.StartsWith('NONPERIODIC-',[StringComparison]::Ordinal);$special=$r3c -and $group.Name -ceq 'NONPERIODIC-CONCENTRATED-8192';$l1=@($valid|ForEach-Object {[double]$_.lod1_ratio});$l0=@($valid|ForEach-Object {[double]$_.lod0_ratio});$cold=@($valid|Where-Object repeat -eq 1|ForEach-Object {[double]$_.cold_overhead_pct});$disk=@($valid|Where-Object cache_first_layer -eq 'disk'|ForEach-Object {[double]$_.cache_disk_hit_us});$coldLookup=@($valid|Where-Object repeat -eq 1|ForEach-Object {[double]$_.cache_first_lookup_us});$adaptiveReduction=@($valid|Where-Object {$_.adaptive_bypasses -ne ''}|ForEach-Object {[double]$_.adaptive_reduction_pct});$nonreg1=if($special){@($l1|Where-Object{$_ -le 0.8}).Count}else{@($l1|Where-Object{$_ -le 1.10}).Count};$nonreg0=@($l0|Where-Object{$_ -le 1.10}).Count;$speed2=if($group.Name -ceq 'CONCENTRATED-8192'){@($l1|Where-Object{$_ -le 0.5}).Count}else{$null};$diskPct=$null;if($disk.Count -and $coldLookup.Count -and (Get-Median ([double[]]$coldLookup)) -gt 0){$diskPct=100*(Get-Median ([double[]]$disk))/(Get-Median ([double[]]$coldLookup))};$nonTimeoutFailure=@($g|Where-Object {$_.timeout_censored -ne $true -and ($_.process_status -match 'FAIL|BLOCK' -or $_.result_status -ne 'PASS')}).Count;$scenarioRows.Add([pscustomobject]@{scenario=$group.Name;attempts=$g.Count;completed_valid=$valid.Count;timeout_censored=@($g|Where-Object timeout_censored -eq $true).Count;other_failed=$nonTimeoutFailure;exact_mismatch_total=(@($valid|Measure-Object query_mismatches -Sum).Sum)+(@($valid|Measure-Object normal_mismatches -Sum).Sum)+(@($valid|Measure-Object picker_mismatches -Sum).Sum);lod0_ratio_median=Get-Median ([double[]]$l0);lod0_nonregression_count=$nonreg0;lod1_ratio_median=Get-Median ([double[]]$l1);lod1_nonregression_or_improvement_count=$nonreg1;lod1_twox_speedup_count=$speed2;lod1_baseline_p50_median_us=Get-Median ([double[]]@($valid|ForEach-Object{[double]$_.lod1_baseline_p50_us}));lod1_candidate_p50_median_us=Get-Median ([double[]]@($valid|ForEach-Object{[double]$_.lod1_optimized_p50_us}));cold_overhead_pct_r01=Get-Median ([double[]]$cold);adaptive_reduction_median_pct=Get-Median ([double[]]$adaptiveReduction);adaptive_reduction_individual_min_pct=if($adaptiveReduction.Count){($adaptiveReduction|Measure-Object -Minimum).Minimum}else{$null};cache_first_layer_sequence=($g|Group-Object cache_first_layer|ForEach-Object{"$($_.Name):$($_.Count)"}) -join ';';fresh_disk_hit_median_us=Get-Median ([double[]]$disk);fresh_disk_hit_pct_of_cold=$diskPct;max_cache_disk_bytes=($valid|Measure-Object cache_disk_bytes -Maximum).Maximum;max_cache_memory_payload_bytes=($valid|Measure-Object cache_memory_bytes -Maximum).Maximum;max_sampled_working_set_bytes=($g|Measure-Object sampled_peak_working_set_bytes -Maximum).Maximum;max_sampled_private_bytes=($g|Measure-Object sampled_peak_private_bytes -Maximum).Maximum;candidate_operations_max=($valid|Measure-Object candidate_operations -Maximum).Maximum;remote_lookup_median_us=Get-Median ([double[]]@($valid|ForEach-Object{[double]$_.cache_remote_edit_lookup_us}));local_edit_rebuild_median_us=Get-Median ([double[]]@($valid|ForEach-Object{[double]$_.cache_local_edit_rebuild_us}))})}
$scenarioRows|Export-Csv -LiteralPath (Join-Path $OutputDirectory 'scenario-summary.csv') -NoTypeInformation -Encoding UTF8
$cacheFiles=Get-ChildItem -LiteralPath (Join-Path $SourceRoot 'cache') -Recurse -File -ErrorAction SilentlyContinue;$cacheRows=foreach($cf in $cacheFiles){$rel=$cf.FullName.Substring((Join-Path $SourceRoot 'cache').Length).TrimStart('\');[pscustomobject]@{relative_path=$rel;bytes=$cf.Length;sha256=(Get-FileHash -LiteralPath $cf.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}};$cacheRows|Export-Csv -LiteralPath (Join-Path $OutputDirectory 'cache-inventory.csv') -NoTypeInformation -Encoding UTF8
$manifestPath=(Join-Path (Split-Path $PSScriptRoot -Parent) '..\..\..\game\tests\fixtures\p3_1_r3c\nonperiodic\scenario-manifest.json');
$totals=[pscustomobject]@{campaign_root=$SourceRoot;source_sha=($runRows|Select-Object -First 1).source_sha;expected_processes=80;recorded_processes=$allProcesses.Count;unique_run_ids=@($allProcesses.run_id|Sort-Object -Unique).Count;exit_zero=(@($allProcesses|Where-Object status -eq 'EXIT_ZERO')).Count;fail_retained=(@($allProcesses|Where-Object status -eq 'FAIL_RETAINED')).Count;timeout_censored=(@($runRows|Where-Object timeout_censored -eq $true)).Count;valid_result_rows=(@($runRows|Where-Object result_status -eq 'PASS')).Count;missing_results=(@($runRows|Where-Object result_status -eq 'MISSING')).Count;process_attribution_verified=(@($allProcesses|Where-Object process_attribution -eq 'CIM_PARENT_CHILD_AND_IMAGE_PIN_VERIFIED')).Count;exact_query_mismatches=(@($runRows|Measure-Object query_mismatches -Sum).Sum);normal_mismatches=(@($runRows|Measure-Object normal_mismatches -Sum).Sum);picker_mismatches=(@($runRows|Measure-Object picker_mismatches -Sum).Sum);cache_files=$cacheFiles.Count;cache_total_bytes=($cacheFiles|Measure-Object Length -Sum).Sum;max_process_working_set_bytes=($allProcesses|Measure-Object sampled_peak_working_set_bytes -Maximum).Maximum;max_process_private_bytes=($allProcesses|Measure-Object sampled_peak_private_bytes -Maximum).Maximum;godot_version='4.7.2.stable.official.ed1daf0bf';manifest_sha256=(Get-FileHash 'game/tests/fixtures/p3_1_r3c/nonperiodic/scenario-manifest.json' -Algorithm SHA256).Hash.ToLowerInvariant();sidecar_sha256=(Get-FileHash 'game/tests/fixtures/p3_1_r3c/nonperiodic/SHA256SUMS.txt' -Algorithm SHA256).Hash.ToLowerInvariant()};$totals|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $OutputDirectory 'campaign-integrity.json') -Encoding UTF8
$scenarioRows|Format-Table scenario,attempts,completed_valid,timeout_censored,lod0_ratio_median,lod0_nonregression_count,lod1_ratio_median,lod1_nonregression_or_improvement_count,lod1_twox_speedup_count,cold_overhead_pct_r01 -AutoSize|Out-String -Width 200
$totals|Format-List
